begin;
create function pg_temp.reject_followup_event() returns trigger language plpgsql as $$ begin
 if current_setting('noreon.test_followup_failure',true)='on' and new.kind='evidence-received' then raise exception 'injected followup failure';end if;return new;
end $$;
create trigger test_followup_failure before insert on public.workspace_followup_events for each row execute function pg_temp.reject_followup_event();
do $$
declare n uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();cl uuid:=gen_random_uuid();a uuid:=gen_random_uuid();req uuid:=gen_random_uuid();sub uuid:=gen_random_uuid();reading uuid;ev bigint;rev integer;w jsonb;s jsonb;draft jsonb;t uuid;before_state jsonb;i integer;
begin
 insert into auth.users(id) values(d),(a),(n);
 insert into public.workspace_clinics(id,name) values(cl,'Fictional monitoring clinic');
 insert into public.workspace_staff(user_id,role,display_name,clinic_id) values(d,'doctor','Fictional monitoring doctor',cl);
 insert into public.workspace_staff(user_id,role,display_name) values(a,'admin','Fictional coordinator');
 insert into public.workspace_staff(user_id,role,display_name,clinic_id) values(n,'nurse','Fictional assigned nurse',cl);
 draft:=jsonb_build_object('explanation','Reviewed','instructions','Fictional plan','followUp','','medicationName','','medicationDose','','medicationInstructions','','medicationTimes','[]'::jsonb);
 w:=jsonb_build_object('revision',0,'startedAt',now(),'tests','[]'::jsonb,'receivedTestIds','[]'::jsonb,'allResultsAt',now(),'consultation','not-required','draft',draft,'draftSaved',false,'publication',null);
 s:=jsonb_build_object('userId',c,'expiresAt',extract(epoch from now()+interval '1 day')*1000,'measurements','[]'::jsonb,'state',jsonb_build_object('consentAccepted',true,'profile',jsonb_build_object('userId',c),'assessment',jsonb_build_object('completedAt',now(),'urgentRule',null)));
 perform public.workspace_create_case(c,s,d);update public.workspace_cases set assigned_nurse_id=n where id=c;rev:=public.workspace_initialize_workflow(c,0,w);
 select evidence_revision into ev from public.workspace_cases where id=c;
 rev:=public.workspace_save_review_draft(c,d,rev,ev,draft);rev:=public.workspace_publish_review(c,d,rev,ev);
 perform public.workspace_create_monitoring(c,d,rev,ev,req,now()+interval '1 hour',now()+interval '2 hours',2,'Fictional explicit monitoring instruction');
 select revision,evidence_revision into rev,ev from public.workspace_cases where id=c;
 begin perform public.workspace_create_monitoring(c,a,rev,ev,gen_random_uuid(),now()+interval '3 hours',now()+interval '4 hours',2,'Admin cannot prescribe');raise exception 'TEST: admin prescribed monitoring';exception when others then if sqlerrm not like '%Assign an active GP%' then raise;end if;end;
 begin perform public.workspace_acknowledge_monitoring(gen_random_uuid(),req);raise exception 'TEST: foreign acknowledgement';exception when others then if sqlerrm not like '%unauthorized%' then raise;end if;end;
 begin perform public.workspace_create_monitoring(c,d,rev,ev,gen_random_uuid(),now()+interval '90 minutes',now()+interval '3 hours',2,'Overlap');raise exception 'TEST: overlap accepted';exception when exclusion_violation then null;end;
 if exists(select 1 from public.workspace_review_tasks where case_id=c and status='open') then raise exception 'TEST: requirement creation opened routine review early';end if;
 -- Move only this disposable test requirement into the past to exercise server-clock dispatch.
 update public.workspace_monitoring_requirements set created_at=now()-interval '3 hours',starts_at=now()-interval '2 hours',ends_at=now()-interval '1 hour' where id=req;
 perform public.workspace_acknowledge_monitoring(c,req);
 perform public.workspace_reconcile_monitoring(c);perform public.workspace_reconcile_monitoring(c);
 if (select count(*) from public.workspace_followup_review_links where requirement_id=req and event='window-ended')<>1 or (select count(*) from public.workspace_followup_work where requirement_id=req and status='open')<>1 then raise exception 'TEST: due dispatch missing or duplicated';end if;
 select revision into rev from public.workspace_cases where id=c;
 rev:=public.workspace_followup_contact(c,a,rev,req,'unreachable','Fictional contact attempt');
 if not exists(select 1 from public.workspace_followup_work where requirement_id=req and status='open') then raise exception 'TEST: contact resolved evidence';end if;
 select revision into rev from public.workspace_cases where id=c;
 rev:=public.workspace_followup_contact(c,a,rev,req,'referred','Fictional referral');
 rev:=public.workspace_followup_contact(c,a,rev,req,'referred','Retry fictional referral');
 if (select count(*) from public.workspace_followup_review_links where requirement_id=req and event='referred')<>1 or (select count(*) from public.workspace_followup_events where requirement_id=req and kind='referred')<>1 then raise exception 'TEST: referral duplicated';end if;
 if exists(select 1 from public.workspace_due_monitoring_cases(null,100) candidate where candidate=c) then raise exception 'TEST: processed window blocks due batch';end if;
 select revision into rev from public.workspace_cases where id=c;
 rev:=public.workspace_followup_contact(c,n,rev,req,'unreachable','Fictional nurse attempted contact');
 if not exists(select 1 from public.workspace_followup_work where requirement_id=req and status='open') then raise exception 'TEST nurse contact completed evidence';end if;
 -- Fill the display list with newer readings, then accept a backdated qualifying reading.
 for i in 1..21 loop perform public.workspace_accept_reading(c,gen_random_uuid(),now()-i*interval '1 minute',120,80,null);end loop;
 select state,evidence_revision into before_state,ev from public.workspace_cases where id=c;
 reading:=public.workspace_accept_reading(c,sub,now()-interval '90 minutes',121,81,null);
 if (select state->'measurements' from public.workspace_cases where id=c) is distinct from before_state->'measurements' then raise exception 'TEST: backdated fixture should be trimmed from display';end if;
 if (select evidence_revision from public.workspace_cases where id=c)<>ev+1 then raise exception 'TEST: hidden durable acceptance did not advance evidence exactly once';end if;
 if not exists(select 1 from public.workspace_monitoring_evidence where requirement_id=req and reading_id=reading and late) then raise exception 'TEST: durable late evidence missing';end if;
 if public.workspace_accept_reading(c,sub,now()-interval '90 minutes',121,81,null)<>reading then raise exception 'TEST: retry not idempotent';end if;
 if (select evidence_revision from public.workspace_cases where id=c)<>ev+1 then raise exception 'TEST: retry bumped evidence';end if;
 begin perform public.workspace_accept_reading(c,sub,now()-interval '90 minutes',122,81,null);raise exception 'TEST: conflicting retry accepted';exception when others then if sqlerrm not like '%measurement conflict%' then raise;end if;end;
 select state,evidence_revision into before_state,ev from public.workspace_cases where id=c;
 perform set_config('noreon.test_followup_failure','on',true);
 begin perform public.workspace_accept_reading(c,gen_random_uuid(),now()-interval '80 minutes',120,80,60);raise exception 'TEST: injected failure not raised';exception when others then if sqlerrm not like '%injected followup failure%' then raise;end if;end;
 perform set_config('noreon.test_followup_failure','off',true);
 if (select state from public.workspace_cases where id=c) is distinct from before_state or (select evidence_revision from public.workspace_cases where id=c)<>ev or (select count(*) from public.workspace_monitoring_evidence where requirement_id=req)<>1 or not exists(select 1 from public.workspace_followup_work where requirement_id=req and status='open') then raise exception 'TEST: failed reading left partial follow-up state';end if;
 perform public.workspace_accept_reading(c,gen_random_uuid(),now()-interval '80 minutes',120,80,60);
 if not exists(select 1 from public.workspace_followup_work where requirement_id=req and status='fulfilled') then raise exception 'TEST: late evidence did not resolve work';end if;
 if not exists(select 1 from public.workspace_review_tasks where case_id=c and status='open') then raise exception 'TEST: evidence arrival closed clinical review';end if;
 select state,revision into before_state,rev from public.workspace_cases where id=c;
 begin perform public.workspace_save_case(c,rev,jsonb_set(before_state,'{measurements}','[]'));raise exception 'TEST: generic reading change accepted';exception when others then if sqlerrm not like '%explicit command%' then raise;end if;end;
 begin perform public.workspace_save_case(c,rev,jsonb_set(before_state,'{acceptedReadingRevision}','999'));raise exception 'TEST: generic marker accepted';exception when others then if sqlerrm not like '%explicit command%' then raise;end if;end;
 select evidence_revision into ev from public.workspace_cases where id=c;
 rev:=public.workspace_save_review_draft(c,d,rev,ev,draft);
 select id into t from public.workspace_review_tasks where case_id=c and status='open';
 rev:=public.workspace_complete_review_no_change(c,d,rev,t,ev,'Fictional review of completed monitoring evidence; no plan change.');
 perform public.workspace_reconcile_monitoring(c);
 if exists(select 1 from public.workspace_review_tasks where case_id=c and status='open') or not exists(select 1 from public.workspace_monitoring_requirements where id=req and status='active' and acknowledged_at is not null) then raise exception 'TEST: replay reopened completed event or no-change altered requirement';end if;
 rev:=public.workspace_cancel_monitoring(c,d,rev,req,'Fictional cancellation after evidence receipt');
 perform public.workspace_accept_reading(c,gen_random_uuid(),now()-interval '70 minutes',120,80,null);
 if (select count(*) from public.workspace_monitoring_evidence where requirement_id=req)<>2 then raise exception 'TEST: cancelled evidence changed';end if;
 if not exists(select 1 from public.workspace_followup_events where requirement_id=req and kind='cancelled' and note='Fictional cancellation after evidence receipt') then raise exception 'TEST: cancellation attribution missing';end if;
 update public.workspace_cases set expires_at=now()-interval '1 second' where id=c;
 if public.workspace_reconcile_monitoring(c)<>0 then raise exception 'TEST: expired case dispatched';end if;
 begin perform public.workspace_accept_reading(c,gen_random_uuid(),now(),120,80,null);raise exception 'TEST: expired reading accepted';exception when others then if sqlerrm not like '%unauthorized%' then raise;end if;end;
 if has_function_privilege('anon','public.workspace_accept_reading(uuid,uuid,timestamptz,integer,integer,integer)','EXECUTE') or has_table_privilege('service_role','public.workspace_accepted_readings','INSERT') then raise exception 'TEST: unprotected durable reading storage';end if;
end $$;
rollback;
